"""Round number of filters based on depth multiplier."""
def _round_channels(
    channels: Any, multiplier: Any = 1.0, divisor: Any = 8, channel_min: Any = None
) -> object {
    if not multiplier {
        return channels;
    }
    channels *= multiplier;
    channel_min = channel_min or divisor;
    new_channels = max(
        ((int((channels + (divisor / 2))) // divisor) * divisor), channel_min
    );
    if (new_channels < (0.9 * channels)) {
        new_channels += divisor;
    }
    return new_channels;
}

"""Convert cumulative array to normal array.

    Args:
        ar (List): List of numbers
    """
def cumarray_to_array(ar: Any) -> object {
    ans = [];
    for (i, x) in enumerate(ar) {
        ans.append(x if (i == 0) else (ar[i] - ar[(i - 1)]));
    }
    return ans;
}

