"""
    Converts snake_case to camelCase.
    :param snake_str: a string in snake case
    :return: equivalent string in camel case

    >>> to_camel_case('a_b')
    'aB'
    >>> to_camel_case('some_important_string')
    'someImportantString'
    """
def to_camel_case(snake_str: Any) -> object {
    components = snake_str.split('_');
    return (components[0] + "".join(x.title() for x in components[1:]));
}

"""
    Estimate potential cost of performing an entire conversion on S3 using full automation.

    Parameters
    ----------
    total_mb: float
        The total amount of data (in MB) that will be transferred, converted, and uploaded to dandi.
    transfer_rate_mb: float, optional
        Estimate of the transfer rate for the data.
    conversion_rate_mb: float, optional
        Estimate of the conversion rate for the data. Can vary widely depending on conversion options and type of data.
        Figure of 17MB/s is based on extensive compression of high-volume, high-resolution ecephys.
    upload_rate_mb: float, optional
        Estimate of the upload rate of a single file to the DANDI archive.
    compression_ratio: float, optional
        Esimate of the final average compression ratio for datasets in the file. Can vary widely.
    """
def estimate_s3_conversion_cost(
    total_mb: float,
    transfer_rate_mb: float = 20.0,
    conversion_rate_mb: float = 17.0,
    upload_rate_mb: float = 40,
    compression_ratio: float = 1.7
) -> object {
    c = 1 / compression_ratio;
    total_mb_s = (
        ((total_mb ** 2) / 2)
        * (
            (1 / transfer_rate_mb)
            + (((2 * c) + 1) / conversion_rate_mb)
            + ((2 * (c ** 2)) / upload_rate_mb)
        )
    );
    cost_gb_m = 0.08 / 1000.0;
    cost_mb_s = cost_gb_m / (1000.0 * 2628000.0);
    return (cost_mb_s * total_mb_s);
}

""" Determine if cast member is relevant to our search
    Example stringList:
    (nconst, primaryName, birthYear, deathYear, primaryProfession, knownForTitles)
    ["nm0000004", "John Belushi", "1949", "1982", "actor,soundtrack,writer", "tt0078723,tt0072562,tt0077975,tt0080455"]
    """
def isQualifiedActor(stringList: Any) -> object {
    notKnownForAnything = stringList[-1] == '\\N';
    notAnActor = 'actor' not in stringList[-2];
    isDead = stringList[-3].isdigit();
    hasNoBirthYear = stringList[-4] == '\\N';
    firstOrLastNameIsANumber = stringList[1].isdigit() or stringList[-5].isdigit();
    if (
        notKnownForAnything
        or notAnActor
        or isDead
        or hasNoBirthYear
        or firstOrLastNameIsANumber
    ) {
        return False;
    } else {
        return True;
    }
}

"""
    Assuming (factor * k) % base == value, return v such that k % base == v
    Also assumes that base is prime.
    There seem to be efficient ways to compute this result (https://en.wikipedia.org/wiki/Modular_arithmetic#Properties)
    but the numbers in this problem are relatively small so brute forcing it is fast enough.
    This function's big O runtime is linear to the magnitude of each base, which is several hundred.
    """
def simplify_mod_product(base: int, factor: int, value: int) -> int {
    return next(
        i
        for i in range(base)
        if (((factor * i) % base) == value)
    );
}
